src/llm_long_term_memory/retrieve/excerp.text:
"""Verbatim turns from the whole archive, found by the question, under a token budget.

The memory-as-index gate (`results/memory-as-index-offline-decision.md`) found that
extracted memories locate the evidence a question needs far less often than searching
the raw archive with the question itself: 50.0% against 78.1% all-gold coverage at
4,000 tokens on train150. Memories are a good state layer and a poor locator. This is
the locator the gate measured — `bm25_turns` — as an answer-time component: BM25 over
every turn in the namespace, whole turns in rank order until the budget is spent, then
shown oldest first with each conversation's date, so the reader can tell when
something was said.

Namespace-scoped by construction: `SQLiteMemoryStore.search_turns` joins turns onto
their session's user, and nothing here reads outside it.
"""

from __future__ import annotations

import math
import re
from collections import defaultdict
from dataclasses import dataclass, field
from datetime import datetime

import numpy as np

from llm_long_term_memory.store import MemoryStore, Turn

RRF_K = 60
_TOKEN = re.compile(r"[a-z0-9]+")


def bm25_rank(query: str, keys: dict[str, str], k1: float = 1.2, b: float = 0.75) -> list[str]:
    """Okapi BM25 over one namespace's turn keys; keys sharing no term are left out.

    Used when a turn's key is not its text alone (`fact_keys`): the store's full-text
    index holds the turns as spoken, so an expanded key has to be ranked here.
    """
    docs = {key: _TOKEN.findall(text.lower()) for key, text in keys.items()}
    n = len(docs)
    average = sum(len(d) for d in docs.values()) / max(1, n)
    frequency: dict[str, int] = defaultdict(int)
    for tokens in docs.values():
        for term in set(tokens):
            frequency[term] += 1
    terms = set(_TOKEN.findall(query.lower()))
    scores: dict[str, float] = {}
    for key, tokens in docs.items():
        counts: dict[str, int] = defaultdict(int)
        for token in tokens:
            counts[token] += 1
        score = 0.0
        for term in terms & counts.keys():
            idf = math.log(1 + (n - frequency[term] + 0.5) / (frequency[term] + 0.5))
            tf = counts[term]
            score += idf * tf * (k1 + 1) / (tf + k1 * (1 - b + b * len(tokens) / average))
        if score > 0:
            scores[key] = score
    return sorted(scores, key=lambda key: -scores[key])


def fact_keyed_texts(store: MemoryStore, user_id: str, turns: list[Turn]) -> dict[str, str]:
    """Each turn's key: its text, followed by the facts anchored to it.

    LongMemEval's fact-augmented key expansion — the facts help a turn be found, and the
    turn is still what is returned. Every memory counts, superseded ones included: a fact
    later replaced still says what its turn was about.
    """
    facts: dict[tuple[str, int], list[str]] = defaultdict(list)
    for memory in store.iter_all(user_id):
        if memory.source_session_id and memory.source_turn_index is not None:
            facts[(memory.source_session_id, memory.source_turn_index)].append(memory.content)
    return {
        turn.id: turn.content
        + (
            "\n" + " ".join(facts[(turn.session_id, turn.turn_index)])
            if facts.get((turn.session_id, turn.turn_index))
            else ""
        )
        for turn in turns
    }


def fuse(*rankings: list[str], k: int = RRF_K) -> list[str]:
    """Reciprocal-rank fusion of turn-id rankings; ties keep first appearance.

    `hybrid-turn-retrieval-offline-v1` measured this against BM25 alone at 4,000
    tokens: 78.1% -> 83.6% all-gold coverage on train150, 86.0% -> 88.2% on heldout100.
    """
    score: dict[str, float] = defaultdict(float)
    first: dict[str, int] = {}
    for ranking in rankings:
        for rank, key in enumerate(ranking, start=1):
            score[key] += 1 / (k + rank)
            first.setdefault(key, len(first))
    return sorted(score, key=lambda key: (-score[key], first[key]))


@dataclass(slots=True)
class ArchiveExcerpts:
    turns: list[Turn] = field(default_factory=list)
    tokens: int = 0
    session_dates: dict[str, datetime | None] = field(default_factory=dict)
    skipped_for_budget: int = 0
    asked_on: datetime | None = None
    """When set, each conversation header also says how long before the question it
    was, so a gap between two dates is a subtraction the code has already done."""

    @property
    def sessions(self) -> list[str]:
        return sorted({turn.session_id for turn in self.turns})

    def render(self) -> str:
        """Oldest conversation first, turns in their original order, each dated."""
        if not self.turns:
            return ""

        def when(session_id: str) -> tuple:
            date = self.session_dates.get(session_id)
            return (date is None, date or datetime.min, session_id)

        by_session: dict[str, list[Turn]] = {}
        for turn in self.turns:
            by_session.setdefault(turn.session_id, []).append(turn)
        blocks = []
        for session_id in sorted(by_session, key=when):
            date = self.session_dates.get(session_id)
            header = f"Conversation on {date:%Y-%m-%d}:" if date else "Conversation (undated):"
            if date and self.asked_on:
                days = (self.asked_on.date() - date.date()).days
                side = "before" if days >= 0 else "after"
                header = (
                    f"Conversation on {date:%Y-%m-%d} ({abs(days)} days, about "
                    f"{abs(days) / 7:.1f} weeks, {side} the question):"
                )
            lines = [
                f"{turn.role}: {turn.content}"
                for turn in sorted(by_session[session_id], key=lambda t: t.turn_index)
            ]
            blocks.append("\n".join([header, *lines]))
        return (
            "Excerpts from the user's earlier conversations, found for this question "
            "(verbatim, oldest first):\n\n" + "\n\n".join(blocks)
        )


def archive_excerpts(
    store: MemoryStore,
    user_id: str,
    question: str,
    max_tokens: int,
    *,
    chars_per_token: float = 4.6,
    candidates: int = 500,
    turn_index=None,
    query_vector: np.ndarray | None = None,
    asked_on: datetime | None = None,
    memory_anchors: list[tuple[str, int]] | None = None,
    fact_keys: bool = False,
    prefer_user: bool = False,
    user_fraction: float = 0.75,
) -> ArchiveExcerpts:
    """Whole turns in rank order until `max_tokens` is spent.

    BM25 alone by default. With `turn_index` (a `NumpyFlatIndex` over turn ids) and the
    question's `query_vector`, the BM25 ranking is fused with a dense ranking of this
    namespace's turns. The dense side searches the whole index and keeps only turns of
    this user's sessions, so another tenant's turn can never be selected however close
    it is.

    `memory_anchors` — `(session_id, turn_index)` of the retrieved memories, in memory
    rank — adds the turns the memories point at as a third ranking. The memory layer holds
    as a user's history grows while turn search does not: at 4x history, 74.7% -> 80.8%
    all-gold coverage (`results/prereg-growth-fusion-offline-v1.md`).

    A turn that would overflow is skipped and filling continues, as the hydrator does
    and as the offline gate measured: a later, shorter turn may still fit.
    """
    result = ArchiveExcerpts(asked_on=asked_on)
    if not 0 <= user_fraction <= 1:
        raise ValueError("user_fraction must be between zero and one")
    if max_tokens <= 0:
        return result
    ranked = store.search_turns(user_id, question, limit=candidates)
    dense_on = turn_index is not None and query_vector is not None and len(turn_index)
    if dense_on or memory_anchors or fact_keys:
        own = {
            turn.id: turn
            for session_id in store.session_ids_for_user(user_id)
            for turn in store.turns_for_session(session_id)
        }
        if fact_keys:
            # BM25 over turn + facts replaces the store's full-text ranking of the turn
            # alone. Measured: the lexical side carries the gain (train150 77.4% ->
            # 81.5%; expanding the dense side alone gave 77.4%).
            lexical = bm25_rank(question, fact_keyed_texts(store, user_id, list(own.values())))
            ranked = [own[tid] for tid in lexical[:candidates]]
        rankings = [[t.id for t in ranked]]
        if dense_on:
            rankings.append(
                [
                    tid
                    for tid, _ in turn_index.search(query_vector, limit=len(turn_index))
                    if tid in own
                ]
            )
        if memory_anchors:
            at = {(turn.session_id, turn.turn_index): turn.id for turn in own.values()}
            led = [at[a] for a in memory_anchors if a in at]
            rankings.append(list(dict.fromkeys(led)))
        own.update({turn.id: turn for turn in ranked})
        ranked = [own[tid] for tid in fuse(*rankings)]
    selected = set()

    def pack(turns, limit):
        for turn in turns:
            if turn.id in selected:
                continue
            cost = max(1, int(len(turn.content) / chars_per_token))
            if result.tokens + cost > limit:
                continue
            result.turns.append(turn)
            selected.add(turn.id)
            result.tokens += cost

    if prefer_user:
        pack([t for t in ranked if t.role == "user"], int(max_tokens * user_fraction))
        pack([t for t in ranked if t.role != "user"], max_tokens)
        pack([t for t in ranked if t.role == "user"], max_tokens)
    else:
        pack(ranked, max_tokens)
    result.skipped_for_budget = sum(t.id not in selected for t in ranked)
    for session_id in result.sessions:
        session = store.get_session(session_id)
        result.session_dates[session_id] = session.started_at if session else None
    return result

src/llm_long_term_memory/store/session_k.text:
"""Reversible database keys for session ids that are only unique per user."""

from __future__ import annotations

_PREFIX = "scoped-session-v1:"


def split_scoped_session_id(value: str | None) -> tuple[str, str] | None:
    """Return ``(user_id, external_id)`` or ``None`` for a legacy/raw id."""
    if value is None or not value.startswith(_PREFIX):
        return None
    length_text, separator, payload = value[len(_PREFIX) :].partition(":")
    if not separator or not length_text.isdigit():
        return None
    user_length = int(length_text)
    if user_length > len(payload):
        return None
    return payload[:user_length], payload[user_length:]


def scoped_session_id(user_id: str, external_id: str) -> str:
    """Return a stable, globally unique storage id for a user's session."""
    parsed = split_scoped_session_id(external_id)
    if parsed is not None:
        if parsed[0] != user_id:
            raise ValueError("a scoped session id cannot be moved to another user")
        return external_id
    return f"{_PREFIX}{len(user_id)}:{user_id}{external_id}"


def external_session_id(value: str | None) -> str | None:
    """Return the client/dataset id, hiding the internal namespace prefix."""
    parsed = split_scoped_session_id(value)
    return parsed[1] if parsed is not None else value

tools/prerequisite_reader_gate.py.text:
"""Public train150 page-selector development gate; dry-run first, resumable, no dev gold."""

from __future__ import annotations

import argparse
import json
import platform
import subprocess
import sys
import time
from pathlib import Path

REPO = Path(__file__).resolve().parent.parent
sys.path[:0] = [str(REPO / "src"), str(REPO / "tools")]
from analysis_io import rows_by_question, sha256_file  # noqa: E402
from grade_saved_recovering import grade_pending  # noqa: E402
from grounded_reader_diagnostic import save_reader  # noqa: E402

QIDS = ("b46e15ed", "9d25d4e0", "gpt4_731e37d7", "gpt4_a1b77f9c", "51a45a95", "eaca4986")
PUBLIC_SHA = "d6f21ea9d60a0d56f34a05b609c79c88a451d2ae03597821ea3d5a9678c3a442"


def main():
    from llm_long_term_memory import cli
    from llm_long_term_memory.config import Settings
    from llm_long_term_memory.evaluation.datasets.longmemeval import load
    from llm_long_term_memory.evaluation.harness import _exclusive
    from llm_long_term_memory.evaluation.recovery import RecoveringJudge
    from llm_long_term_memory.llm.usage import UsageTracker
    from llm_long_term_memory.runtime.evidence_pages import archive_pages
    from llm_long_term_memory.runtime.grounded_answering import personal_archive_review
    from llm_long_term_memory.store import external_session_id

    parser = argparse.ArgumentParser()
    parser.add_argument("--execute", action="store_true")
    parser.add_argument("--grade", action="store_true")
    parser.add_argument("--label", default="prerequisite-reader-v18-v1")
    args = parser.parse_args()
    if not args.label or any(c not in "abcdefghijklmnopqrstuvwxyz0123456789-_" for c in args.label):
        raise ValueError("invalid namespace")
    settings = Settings()
    dataset = (settings.data_dir / "longmemeval_s_cleaned.json").resolve()
    if sha256_file(dataset) != PUBLIC_SHA:
        raise ValueError("public dataset changed")
    train_path = REPO / "results/manifests/train150.json"
    allowed = set(json.loads(train_path.read_text(encoding="utf-8"))["question_ids"])
    if not set(QIDS) <= allowed:
        raise ValueError("gate must stay within exposed train150")
    instances = {i.question_id: i for i in load("s", settings.data_dir) if i.question_id in QIDS}
    gate = json.loads(
        (REPO / "results/analysis/role-paged-growth-v3.train150.json").read_text(encoding="utf-8")
    )
    for factor in ("1", "2", "4"):
        measured = gate["by_factor"][factor]
        if measured["covered"] != 146 or measured["complete_archives"] != 150:
            raise ValueError("registered offline growth gate failed")
    cfg, _, runner, judge, usage = cli._build(
        "two_stage_raw_primary_grounded_v18",
        "configs/fallback.yaml",
        "train150",
        client_override=None if args.execute else object(),
        read_only_store=True,
    )
    try:
        if args.execute:
            runner.client.max_retries = 2
            runner.client.max_transport_retries = 2
        rows = []
        for qid, instance in instances.items():
            originals = {
                (s.session_id, i): (t.role, t.content)
                for s in instance.sessions
                for i, t in enumerate(s.turns)
            }
            raw_count = 0
            for sid in runner.store.session_ids_for_user(qid):
                for turn in runner.store.turns_for_session(sid):
                    if originals.get((external_session_id(sid), turn.turn_index)) != (
                        turn.role,
                        turn.content,
                    ):
                        raise ValueError("raw history is not the exact public same-user corpus")
                    raw_count += 1
            public_sessions = {s.session_id for s in instance.sessions}
            memories = runner.store.iter_all(qid)
            for memory in memories:
                if (
                    memory.user_id != qid
                    or not memory.source_session_id
                    or external_session_id(memory.source_session_id) not in public_sessions
                ):
                    raise ValueError("derived memory lacks same-user public provenance")
            routed = personal_archive_review(instance.question)
            pages = (
                archive_pages(runner.store, qid, roles=("user",), split_oversized=True)
                if routed
                else None
            )
            if pages and not pages.complete:
                raise ValueError("incomplete archive preflight")
            rows.append(
                {
                    "question_id": qid,
                    "public_raw_turns": raw_count,
                    "public_derived_memories": len(memories),
                    "user_review": routed,
                    "pages": len(pages.pages) if pages else 0,
                    "review_tokens": sum(int(len(p.render()) / 4.6) for p in pages.pages)
                    if pages
                    else 0,
                }
            )
        expected = sum(r["pages"] for r in rows) + 2 * len(rows)
        if expected > 40:
            raise ValueError("registered answerer call ceiling exceeded")
        paths = [
            *list((REPO / "src").rglob("*.py")),
            Path(__file__),
            train_path,
            REPO / "tools/grounded_reader_diagnostic.py",
            REPO / "tools/grade_saved_recovering.py",
            REPO / "results/prereg-prerequisite-reader-v18-v1.md",
            REPO / "configs/fallback.yaml",
            REPO / "results/analysis/role-paged-growth-v3.train150.json",
            dataset,
            REPO / "stores/train150.db",
        ]
        if args.label.endswith("-v9"):
            paths.append(REPO / "results/prereg-prerequisite-reader-v18-v9.md")
        if args.label.endswith(("-v8", "-v9")):
            paths.append(REPO / "results/prereg-prerequisite-reader-v18-v8.md")
        if args.label.endswith(("-v7", "-v8", "-v9")):
            paths.append(REPO / "results/prereg-prerequisite-reader-v18-v7.md")
        if args.label.endswith(("-v6", "-v7", "-v8", "-v9")):
            paths.append(REPO / "results/prereg-prerequisite-reader-v18-v6.md")
        if args.label.endswith(("-v5", "-v6", "-v7", "-v8", "-v9")):
            paths.append(REPO / "results/prereg-prerequisite-reader-v18-v5.md")
        if args.label.endswith(("-v4", "-v5", "-v6", "-v7", "-v8", "-v9")):
            paths.append(REPO / "results/prereg-prerequisite-reader-v18-v4.md")
        if args.label.endswith(("-v3", "-v4", "-v5", "-v6", "-v7", "-v8", "-v9")):
            paths.append(REPO / "results/prereg-prerequisite-reader-v18-v3.md")
        if args.label.endswith(("-v2", "-v3", "-v4", "-v5", "-v6", "-v7", "-v8", "-v9")):
            paths.append(REPO / "results/prereg-prerequisite-reader-v18-v2.md")
        for stem in ("train150-index", "train150-turn-key-index"):
            paths.extend(
                REPO / "stores" / f"{stem}{suffix}"
                for suffix in (".npy", ".ids.json", ".manifest.json")
                if suffix != ".manifest.json" or (REPO / "stores" / f"{stem}{suffix}").exists()
            )
        identity = {
            "experiment_class": "exposed-train150-mechanism-development",
            "question_ids": list(QIDS),
            "baseline": "historical v15; no paired accuracy estimate",
            "models": cfg.models.model_dump(),
            "prompt_version": runner.answer_prompt_version,
            "sample_count": len(QIDS),
            "temperature": 0,
            "seed": "provider unsupported",
            "python": platform.python_version(),
            "git_sha": subprocess.check_output(["git", "rev-parse", "HEAD"], text=True).strip(),
            "files": {str(p.relative_to(REPO)): sha256_file(p) for p in paths},
            "preflight": rows,
            "max_nominal_reader_calls": expected,
            "judge_calls": len(rows),
            "recovery": {"max_recoveries": 3, "max_wait_seconds": 180},
            "provider_retry_policy": {
                "max_retries": 2,
                "max_transport_retries": 2,
                "timeout_seconds": 180,
            },
        }
        source_snapshot = REPO / f"results/analysis/{args.label}.source-snapshot.json"
        snapshot = {
            "files": {
                p: {"sha256": sha, "text": (REPO / p).read_text(encoding="utf-8")}
                for p, sha in identity["files"].items()
                if Path(p).suffix in {".py", ".yaml", ".md"}
            }
        }
        if source_snapshot.exists():
            if json.loads(source_snapshot.read_text(encoding="utf-8")) != snapshot:
                raise ValueError("source snapshot changed")
        elif args.execute:
            raise ValueError("create frozen source preview before execution")
        else:
            source_snapshot.write_text(json.dumps(snapshot, indent=2) + "\n", encoding="utf-8")
        identity["source_snapshot_sha256"] = sha256_file(source_snapshot)
        base = REPO / f"results/raw/{args.label}"
        inventory_path = base.with_suffix(".execution.json")
        readers_path = base.with_suffix(".readers.jsonl")
        grades_path = base.with_suffix(".grades.jsonl")
        usage_path = base.with_suffix(".usage.json")
        if not args.execute:
            preview = REPO / f"results/analysis/{args.label}.preview.json"
            if preview.exists():
                raise ValueError("preview namespace exists")
            preview.write_text(json.dumps(identity, indent=2) + "\n", encoding="utf-8")
            print(
                json.dumps(
                    {"provider_calls": 0, "preflight": rows, "max_nominal_reader_calls": expected}
                )
            )
            return 0
        preview = json.loads(
            (REPO / f"results/analysis/{args.label}.preview.json").read_text(encoding="utf-8")
        )
        if identity != preview:
            raise ValueError("preview identity changed")
        with _exclusive(readers_path):
            if inventory_path.exists():
                if json.loads(inventory_path.read_text(encoding="utf-8")) != identity:
                    raise ValueError("execution identity changed")
            else:
                if any(p.exists() for p in (readers_path, grades_path, usage_path)):
                    raise ValueError("unbound namespace")
                inventory_path.write_text(json.dumps(identity, indent=2) + "\n", encoding="utf-8")
            digest = sha256_file(inventory_path)
            readers = rows_by_question(readers_path) if readers_path.exists() else {}
            grades = rows_by_question(grades_path) if grades_path.exists() else {}
            if not set(readers) <= set(QIDS) or any(
                r["inventory_sha256"] != digest for r in readers.values()
            ):
                raise ValueError("foreign readers")
            if (readers or grades) and not usage_path.exists():
                raise ValueError("missing usage provenance")
            if usage_path.exists():
                usage.records[:] = UsageTracker._load_records(usage_path)
            started = time.time()
            try:
                if args.grade:
                    if set(readers) != set(QIDS):
                        raise ValueError("complete readers before grading")
                    wrapped = RecoveringJudge(
                        judge, usage, usage_path, base.with_suffix(".recovery.json"), digest
                    )
                    with grades_path.open("a", encoding="utf-8") as sink:
                        grade_pending(
                            wrapped,
                            instances,
                            readers,
                            grades,
                            sink,
                            lambda: usage.save(usage_path),
                        )
                else:
                    with readers_path.open("a", encoding="utf-8") as sink:
                        for qid in QIDS:
                            if qid not in readers:
                                readers[qid] = save_reader(
                                    runner, instances[qid], sink, digest, "prerequisite-pages"
                                )
                                usage.save(usage_path)
                                print(
                                    json.dumps(
                                        {
                                            "reader_completed": len(readers),
                                            "total": len(QIDS),
                                            "question_id": qid,
                                        }
                                    ),
                                    flush=True,
                                )
            finally:
                usage.save(usage_path)
            if any(sha256_file(REPO / name) != sha for name, sha in identity["files"].items()):
                raise ValueError("source changed during execution")
            print(
                json.dumps(
                    {
                        "readers": len(readers),
                        "grades": len(grades),
                        "elapsed_seconds": time.time() - started,
                        "usage": usage.summary(),
                    }
                ),
                flush=True,
            )
    finally:
        runner.store.close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

